#!/usr/bin/env bash
# Create the circleguard-secrets Secret of one environment from the private
# file infra/environments/.env.<env> (generated by create-env.sh, never committed).
#   bash infra/k8s/secrets.sh dev|stage|prod      (KUBE_CONTEXT selects the cluster)
# Values never travel as command-line arguments (they would show in the process
# list): each one goes to a 0600 file in a private temporary directory that is
# removed on exit, and kubectl reads the files. Nothing sensitive is printed.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=lib.sh
source "$HERE/lib.sh"
env="${1:-}"
case "$env" in
  dev|stage|prod) ;;
  *) echo 'Usage: bash infra/k8s/secrets.sh dev|stage|prod' >&2; exit 2 ;;
esac
file="$HERE/../environments/.env.$env"
[[ -f "$file" ]] || { echo "Missing $file: run infra/environments/create-env.sh $env" >&2; exit 1; }
select_cluster "$env"
ns="circleguard-$env"

umask 077
base="${XDG_RUNTIME_DIR:-}"
[[ -d "$base" && -w "$base" ]] || base="${TMPDIR:-/tmp}"
work="$(mktemp -d "$base/cg-secrets.XXXXXX")"
trap 'rm -rf "$work"' EXIT

args=()
for key in DB_USER DB_PASSWORD NEO4J_PASSWORD LDAP_ADMIN_PASSWORD REDIS_PASSWORD JWT_SECRET QR_SECRET VAULT_SECRET VAULT_SALT VAULT_HASH_SALT; do
  value="$(grep -E "^${key}=" "$file" | head -1 | cut -d= -f2-)"
  [[ -n "$value" ]] || { echo "$key is empty in $file" >&2; exit 1; }
  printf '%s' "$value" > "$work/$key"
  args+=("--from-file=${key}=$work/$key")
done

kc create namespace "$ns" --dry-run=client -o yaml | kc apply -f - >/dev/null
kc -n "$ns" create secret generic circleguard-secrets "${args[@]}" --dry-run=client -o yaml | kc apply -f - >/dev/null
echo "Secret circleguard-secrets applied in $ns"
